# Let's identify connected components of each non-majority color; if component size==1, recolor it to... which neighbor? nearest larger block color?
def comps(g, minsize=2):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    dirs=[(dy,dx) for dy in(-1,0,1) for dx in(-1,0,1) if dy or dx]
    for r in range(H):
        for c in range(W):
            if (r,c) in seen: continue
            v=g[r][c]; stack=[(r,c)]; cellset={(r,c)}; gen=True
            while stack and gen:
                x,y=stack.pop()
                for dy,dx in dirs:
                    nx,ny=x+dy,y+dx
                    if 0<=nx<H and 0<=ny<W and (nx,ny) not in cellset and g[nx][ny]==v:
                        cellset.add((nx,ny)); stack.append((nx,ny))
            gen=False
            if len(cellset)>=minsize:
                for p in cellset: seen.add(p)
                out.append((v,cellset))
    return out
